    /**
     * Tests getting all TrainingCourses.
     *
     * @return    Collection
     */
    public List<TrainingCourse> testGetAll() throws Throwable {
    LOGGER.info( "TrainingCourseTest:testGetAll() - Retrieving Collection of TrainingCourses:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all TrainingCourse : " );
    List<TrainingCourse> collection  = null;

    try {
        // call the static get method on the TrainingCourseService
        collection = service.getAllTrainingCourse();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            TrainingCourse currEntity  = null;
            Iterator<TrainingCourse> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getTrainingCourseId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

